describe('Order Confirmation After Successful Payment', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display order confirmation after successful payment', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payments/process').as('paymentProcess');

    // Fill in order details
    cy.get('[data-testid="order-form-name"]').type('John Doe');
    cy.get('[data-testid="order-form-email"]').type('john.doe@example.com');
    cy.get('[data-testid="order-form-address"]').type('123 Main St, Anytown, USA');
    cy.get('[data-testid="order-form-phone"]').type('555-1234');
    cy.get('[data-testid="order-form-total"]').type('150.00');

    // Submit the order
    cy.get('[data-testid="order-submit-button"]').click();

    // Wait for payment API call
    cy.wait('@paymentProcess');

    // Verify success message appears
    cy.get('[data-testid="order-confirmation-message"]').should('be.visible');
    cy.get('[data-testid="order-confirmation-message"]').should('contain', 'Payment successful');

    // Verify order details are displayed
    cy.get('[data-testid="order-confirmation-details"]').should('be.visible');
    cy.get('[data-testid="order-confirmation-details"]').should('contain', 'John Doe');
    cy.get('[data-testid="order-confirmation-details"]').should('contain', '123 Main St, Anytown, USA');

    // Verify order ID is displayed
    cy.get('[data-testid="order-confirmation-order-id"]').should('be.visible');
    cy.get('[data-testid="order-confirmation-order-id"]').should('contain', 'ORD-123456');

    // Verify success toast appears
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Order confirmed');

    // Verify payment success notification
    cy.get('[data-testid="payment-success-notification"]').should('be.visible');
    cy.get('[data-testid="payment-success-notification"]').should('contain', 'Payment processed');

    // Verify order summary
    cy.get('[data-testid="order-summary"]').should('be.visible');
    cy.get('[data-testid="order-summary"]').should('contain', 'Total: $150.00');

    // Verify back button is available
    cy.get('[data-testid="order-summary-back-button"]').should('be.visible');
  });

  it('should display error message when payment fails', () => {
    // Intercept the payment API call with a failure response
    cy.intercept('POST', '/api/payments/process', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('paymentProcessFail');

    // Fill in order details
    cy.get('[data-testid="order-form-name"]').type('Jane Smith');
    cy.get('[data-testid="order-form-email"]').type('jane.smith@example.com');
    cy.get('[data-testid="order-form-address"]').type('456 Elm St, Othertown, USA');
    cy.get('[data-testid="order-form-phone"]').type('555-6789');
    cy.get('[data-testid="order-form-total"]').type('200.00');

    // Submit the order
    cy.get('[data-testid="order-submit-button"]').click();

    // Wait for payment API call
    cy.wait('@paymentProcessFail');

    // Verify error message appears
    cy.get('[data-testid="order-confirmation-error-message"]').should('be.visible');
    cy.get('[data-testid="order-confirmation-error-message"]').should('contain', 'Payment failed');

    // Verify error toast appears
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Payment processing error');

    // Verify order was not confirmed
    cy.get('[data-testid="order-confirmation-message"]').should('not.exist');

    // Verify user is redirected to error page
    cy.url().should('include', '/error');

    // Verify user can retry payment
    cy.get('[data-testid="retry-payment-button"]').should('be.visible');
  });
});
